export type MessageCallback = (data: Message) => void;

/**
 * A Builder manages a single custom widget builder popup window.
 * It owns the window reference, the message event listener registered on the
 * parent window and the map of message listeners registered by consumers.
 */
export class Builder {
  // The builder popup window. Public so consumers can inspect/act on it.
  builderWindow: Window | null = null;

  // Stores message listener callbacks keyed by message type.
  onMessageMap: Map<string, MessageCallback[]> = new Map();

  constructor() {
    this.builderWindow = window.open(
      `${window.location.pathname}/builder`,
      "_blank",
    );

    window.addEventListener("message", this.messageHandler);
  }

  // Routes messages coming from the builder window to the registered callbacks.
  messageHandler = (event: MessageEvent) => {
    if (event.source === this.builderWindow) {
      const handlerList = this.onMessageMap.get(event.data.type);

      if (handlerList) {
        handlerList.forEach((fn) => fn(event.data));
      }
    }
  };

  /**
   * Register a callback for a given message type.
   * Returns a cancel function that removes the callback.
   */
  onMessage(type: string, callback: MessageCallback) {
    let eventHandlerList = this.onMessageMap.get(type);

    if (eventHandlerList && eventHandlerList instanceof Array) {
      eventHandlerList.push(callback);
    } else {
      eventHandlerList = [callback];
      this.onMessageMap.set(type, eventHandlerList);
    }

    return () => {
      if (eventHandlerList) {
        const index = eventHandlerList.indexOf(callback);

        if (index > -1) {
          eventHandlerList.splice(index, 1);
        }
      }
    };
  }

  // Sends a message to the builder window.
  postMessage(message: unknown) {
    this.builderWindow?.postMessage(message, "*");
  }

  // Returns true if the builder window is still open.
  isConnected() {
    return !!(this.builderWindow && !this.builderWindow.closed);
  }

  // Brings the builder window into focus.
  focus() {
    if (this.isConnected()) {
      this.builderWindow?.focus();
    }
  }

  /**
   * Removes the message event listener and optionally closes the window.
   */
  close(closeWindow?: boolean) {
    window.removeEventListener("message", this.messageHandler);

    if (closeWindow) {
      this.builderWindow?.close();
    }
  }
}

export type BuilderFactory = (widgetId: string) => Builder;

/**
 * Manages the lifecycle of Builder instances keyed by widget id. The Builder
 * creation is delegated to an injectable factory so the actual window handling
 * can be swapped out (e.g. in tests).
 */
class CustomWidgetBuilderService {
  private builders: Map<string, Builder> = new Map();

  private builderFactory: BuilderFactory = () => new Builder();

  // Sets the factory used to create Builder instances.
  setBuilderFactory(factory: BuilderFactory) {
    this.builderFactory = factory;
  }

  // Creates a builder for the widget, stores and returns it.
  createBuilder(widgetId: string) {
    const builder = this.builderFactory(widgetId);

    this.builders.set(widgetId, builder);

    return builder;
  }

  // Returns the connection status of the widget's builder.
  isConnected(widgetId: string) {
    const builder = this.builders.get(widgetId);

    return builder ? builder.isConnected() : false;
  }

  // Focuses the widget's builder window.
  focus(widgetId: string) {
    this.builders.get(widgetId)?.focus();
  }

  // Closes and removes the widget's builder.
  closeBuilder(widgetId: string, closeWindow?: boolean) {
    const builder = this.builders.get(widgetId);

    if (builder) {
      builder.close(closeWindow);

      this.builders.delete(widgetId);
    }
  }

  // Retrieves the builder instance or returns undefined.
  getBuilder(widgetId: string) {
    return this.builders.get(widgetId);
  }
}

export default new CustomWidgetBuilderService();
